using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class DuplicateKeyReceiptTests(ITestOutputHelper logger)
{
    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver
            {
            }

            [MessagePackObject]
            public class DupKeyObject
            {
                [Key(0)]
                public int AlphaMember { get; set; }

                [Key(0)]
                public int BetaMember { get; set; }
            }
        }
        """;

    [Fact]
    public async Task DuplicateIntKey_IsReportedOrBothMembersSerialized()
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3);
        var framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = Enumerable.Concat<MetadataReference>(framework, ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        var compilation = CSharpCompilation.Create(
            "DupKeyAsm",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        ImmutableArray<DiagnosticAnalyzer> analyzers = typeof(MessagePackGenerator).Assembly.GetTypes()
            .Where(t => !t.IsAbstract && typeof(DiagnosticAnalyzer).IsAssignableFrom(t) && t.GetCustomAttributes(typeof(DiagnosticAnalyzerAttribute), false).Length > 0)
            .Select(t => (DiagnosticAnalyzer)Activator.CreateInstance(t)!)
            .ToImmutableArray();

        ImmutableArray<Diagnostic> analyzerDiagnostics = await compilation.WithAnalyzers(analyzers).GetAnalyzerDiagnosticsAsync();

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();
        string generatedText = string.Join("\n", runResult.GeneratedTrees.Select(t => t.ToString()));

        var allDiagnostics = analyzerDiagnostics.Concat(generatorDiagnostics).Concat(runResult.Diagnostics).ToList();
        foreach (Diagnostic d in allDiagnostics)
        {
            logger.WriteLine(d.ToString());
        }

        logger.WriteLine(generatedText);

        bool duplicateReported = allDiagnostics.Any(d => d.Id.StartsWith("MsgPack", StringComparison.Ordinal) && d.Severity == DiagnosticSeverity.Error);
        bool bothMembersSerialized = generatedText.Contains("AlphaMember") && generatedText.Contains("BetaMember");

        Assert.True(
            duplicateReported || bothMembersSerialized,
            "Duplicate [Key(0)] was neither reported as an error nor were both members serialized; BetaMember is silently dropped.");
    }
}
